public record PriceItem(BigDecimal original, BigDecimal member, int qty) {
    public BigDecimal amountOf(boolean member) {
        return (member ? member : original).multiply(BigDecimal.valueOf(qty)); } }
public sealed interface CouponRule permits ThresholdCoupon, PercentCoupon {
    BigDecimal discountOf(BigDecimal total, boolean member); }
public static PriceResult calculate(List<PriceItem> items, CouponRule coupon, boolean m) {
    BigDecimal original = items.stream().map(i -> i.amountOf(m))
        .reduce(BigDecimal.ZERO, BigDecimal::add);
    BigDecimal discount = coupon == null ? BigDecimal.ZERO : coupon.discountOf(original, m);
    return new PriceResult(original, discount,
        original.subtract(discount).setScale(2, RoundingMode.HALF_UP));
}

