public final class PriceItem {                  // Java 8 value object
    private final BigDecimal original, member;
    private final int qty;
    public PriceItem(BigDecimal original, BigDecimal member, int qty) {
        this.original = original; this.member = member; this.qty = qty;
    }
    public BigDecimal amountOf(boolean isMember) {   // no setters
        return (isMember ? member : original).multiply(BigDecimal.valueOf(qty));
    }
}
